 static string OriginalFinalPath(string path){using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){var b=new StringBuilder(32768);uint n=GetFinalPathNameByHandle(f.SafeFileHandle.DangerousGetHandle(),b,32768,0);Require(n>0&&n<32768,"Original fixture final path");return b.ToString();}}
 static void Require(bool ok,string reason){if(!ok)throw new Exception(reason+" (Win32 "+Marshal.GetLastWin32Error()+")");}
 static string Input(){IntPtr h=OpenInputDesktop(0,false,1);Require(h!=IntPtr.Zero,"Input desktop query");try{int n;StringBuilder b=new StringBuilder(256);Require(GetUserObjectInformation(h,2,b,512,out n),"Input desktop name");return b.ToString();}finally{CloseDesktop(h);}}
 static void Owned(IntPtr window,PI pi,long start){uint pid;GetWindowThreadProcessId(window,out pid);long actual,e,k,u;Require(pid==pi.pid && WaitForSingleObject(pi.process,0)==258,"Owned HWND/process identity");Require(GetProcessTimes(pi.process,out actual,out e,out k,out u)&&actual==start,"Owned process start identity");}
 static AutomationElement[] Nodes(AutomationElement root){List<AutomationElement> items=new List<AutomationElement>();Queue<AutomationElement> todo=new Queue<AutomationElement>();todo.Enqueue(root);TreeWalker walker=TreeWalker.RawViewWalker;while(todo.Count>0){AutomationElement e=todo.Dequeue();items.Add(e);if(items.Count>256)throw new Exception("UIA subtree node limit");for(AutomationElement child=walker.GetFirstChild(e);child!=null;child=walker.GetNextSibling(child)){todo.Enqueue(child);if(todo.Count+items.Count>256)throw new Exception("UIA subtree queue limit");}}return items.ToArray();}
 static AutomationElement Find(AutomationElement root,string name,ControlType type){AutomationElement found=null;foreach(AutomationElement e in Nodes(root)){if(e.Current.Name==name&&e.Current.ControlType==type){Require(found==null,"Duplicate accessible field "+name);found=e;}}Require(found!=null,"Missing accessible field "+name);return found;}
 static string Read(AutomationElement e){object pattern;string value;if(e.TryGetCurrentPattern(ValuePattern.Pattern,out pattern))value=((ValuePattern)pattern).Current.Value;else if(e.TryGetCurrentPattern(TextPattern.Pattern,out pattern))value=((TextPattern)pattern).DocumentRange.GetText(65537);else throw new Exception("No readable text pattern");Require(value.Length<=65536,"UIA text limit");return value;}
 static AutomationElement Activate(IntPtr window,PI pi,long start,string output){List<Dictionary<string,object>> probes=new List<Dictionary<string,object>>();foreach(int objectId in new int[]{-25,-4}){Owned(window,pi,start);IntPtr response;IntPtr delivered=SendMessageTimeout(window,0x003d,IntPtr.Zero,new IntPtr(objectId),0x0002,2000,out response);var row=new Dictionary<string,object>();row["object_id"]=objectId;row["delivered"]=delivered!=IntPtr.Zero;row["response"]=response.ToInt64();row["last_error"]=Marshal.GetLastWin32Error();probes.Add(row);Save(Path.Combine(output,"provider-probes.json"),probes);Require(delivered!=IntPtr.Zero,"Owned WM_GETOBJECT timed out/failed");}AutomationElement root=null;List<int> counts=new List<int>();for(int i=0;i<50;i++){Owned(window,pi,start);root=AutomationElement.FromHandle(window);Require(root!=null&&root.Current.ProcessId==pi.pid,"UIA root identity");counts.Add(Nodes(root).Length);if(counts[counts.Count-1]>1)break;Thread.Sleep(100);}Save(Path.Combine(output,"provider-subtree-counts.json"),counts);return root;}
 static string Hash(string text){using(var sha=System.Security.Cryptography.SHA256.Create()){return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(text))).Replace("-","").ToLowerInvariant();}}
 static void Pump(IntPtr window,PI pi,long start,int delay){Owned(window,pi,start);Require(PostMessage(window,15,IntPtr.Zero,IntPtr.Zero),"Owned WM_PAINT");Thread.Sleep(delay);}
 static void InputEvidence(AutomationElement e,string expected,string observed,string output,string stage,IntPtr window,PI pi,long start){var row=new Dictionary<string,object>();row["field"]=e.Current.Name;row["stage"]=stage;row["expected_length"]=expected.Length;row["actual_length"]=observed.Length;row["expected_sha256"]=Hash(expected);row["actual_sha256"]=Hash(observed);row["actual_synthetic_uia_value"]=observed.Length<=1024?observed:"[bounded omission]";row["synthetic_only"]=true;var bounds=e.Current.BoundingRectangle;row["bounds_left"]=bounds.Left;row["bounds_top"]=bounds.Top;row["bounds_width"]=bounds.Width;row["bounds_height"]=bounds.Height;string field=expected.StartsWith("https://",StringComparison.Ordinal)?"url":"cookie";Save(Path.Combine(output,"input-"+field+"-"+stage+".json"),row);Capture(window,pi,start,Path.Combine(output,"input-"+field+"-"+stage+".png"));}
 static void Invoke(AutomationElement e){object pattern=null;Require(e.Current.IsEnabled&&e.TryGetCurrentPattern(InvokePattern.Pattern,out pattern),"Invoke pattern unavailable/disabled");((InvokePattern)pattern).Invoke();}
 static void Capture(IntPtr window,PI pi,long start,string path){Owned(window,pi,start);Rect r;Require(GetClientRect(window,out r)&&r.right>0&&r.bottom>0&&r.right<=4096&&r.bottom<=4096,"Screenshot dimensions");using(var bitmap=new System.Drawing.Bitmap(r.right,r.bottom))using(var graphics=System.Drawing.Graphics.FromImage(bitmap)){IntPtr dc=graphics.GetHdc();bool ok;try{ok=PrintWindow(window,dc,3);}finally{graphics.ReleaseHdc(dc);}Require(ok,"Private PrintWindow unsupported");bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
 static void Save(string path,object value){string text=new JavaScriptSerializer().Serialize(value);Require(Encoding.UTF8.GetByteCount(text)<=65536,"Evidence JSON limit");File.WriteAllText(path,text,new UTF8Encoding(false));}


 static Dictionary<string,string> originalProtected;
 static bool Label(AutomationElement app,string text){foreach(var n in Nodes(app))if(n.Current.Name==text||n.Current.Name.Contains(text))return true;return false;}
 static string FileHash(string path){using(var f=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var sha=System.Security.Cryptography.SHA256.Create()){Require(f.Length<=268435456,"Fixture hash bound");return BitConverter.ToString(sha.ComputeHash(f)).Replace("-","").ToLowerInvariant();}}
 static string Plain(string path,string root){Require(Path.IsPathRooted(path),"Absolute fixture path required");string full=Path.GetFullPath(path),basePath=Path.GetFullPath(root).TrimEnd('\\')+"\\";Require(full.StartsWith(basePath,StringComparison.OrdinalIgnoreCase),"Fixture containment");string current=full;while(current!=null){if(File.Exists(current)||Directory.Exists(current))Require((File.GetAttributes(current)&FileAttributes.ReparsePoint)==0,"Fixture reparse rejected");current=Path.GetDirectoryName(current);}return full;}
 static Dictionary<string,string> Protected(Dictionary<string,object> manifest,string root){var result=new Dictionary<string,string>();var files=(System.Collections.IEnumerable)manifest["protected_files"];foreach(object item in files){string path=Plain((string)item,root);Require(File.Exists(path)&&!result.ContainsKey(path),"Original protected fixture");result[path]=FileHash(path);Require(result.Count<=32,"Protected fixture count");}Require(result.Count>0,"Protected fixture count");return result;}
 static void VerifyRecovery(AutomationElement app,IntPtr window,PI pi,long start,string root,string output,Dictionary<string,object> result){
 string manifestPath=Plain(Path.Combine(root,"gui-recovery-case.json"),root);Require(new FileInfo(manifestPath).Length<=65536,"Manifest bound");var manifest=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(manifestPath));Require(Convert.ToInt32(manifest["schema"])==1,"Manifest schema");string mode=(string)manifest["case"];Require(mode=="completed"||mode=="pending"||mode=="malformed","Case domain");result["case"]=mode;
 string pending="관리 도구의 실행 종료를 확인하지 못했습니다. 파일 보호를 위해 관리 도구 실행과 변경을 보류합니다.",failed="이전 관리 도구 실행 기록을 안전하게 확인하지 못했습니다. 앱 전용 폴더의 권한을 확인하고 다시 시도하세요.",done="이전 작업 상태 재확인",retry="이전 작업 다시 확인";
 string expected=mode=="completed"?done:mode=="pending"?pending:failed;for(int i=0;i<200&&!Label(app,expected);i++)Pump(window,pi,start,100);Require(Label(app,expected),"Actual startup recovery state missing");Save(Path.Combine(output,"startup-labels.json"),Array.ConvertAll(Nodes(app),delegate(AutomationElement n){return new{name=n.Current.Name,enabled=n.Current.IsEnabled,offscreen=n.Current.IsOffscreen,left=n.Current.BoundingRectangle.Left,top=n.Current.BoundingRectangle.Top};}));Capture(window,pi,start,Path.Combine(output,"startup.png"));result["actual_state"]=expected;
 var before=originalProtected;if(mode!="completed"){var button=Find(app,retry,ControlType.Button);Require(button.Current.IsEnabled,"Recovery retry disabled");Invoke(button);Pump(window,pi,start,300);for(int i=0;i<200&&!Label(app,expected);i++)Pump(window,pi,start,100);Require(Label(app,expected),"Retry failed to retain correct state");result["retry_invoked"]=true;Capture(window,pi,start,Path.Combine(output,"retry.png"));}
 var startButton=Find(app,"다운로드 시작",ControlType.Button);Require(mode!="malformed"||!startButton.Current.IsEnabled,"Malformed startup allowed download");if(mode=="completed"){var removed=(System.Collections.IEnumerable)manifest["removed_files"];int removalCount=0;foreach(object item in removed){Require(++removalCount<=16,"Original removal count");Require(!File.Exists(Plain((string)item,root))&&!Directory.Exists(Plain((string)item,root)),"Completed original managed files remain");}Require(removalCount>=9,"Original removal proof count");Require(!Label(app,pending),"Completed managed pending still displayed");Invoke(Find(app,"작업 이력",ControlType.Button));for(int i=0;i<100&&!Label(app,"비정상 중단됨");i++)Pump(window,pi,start,100);Require(Label(app,"비정상 중단됨"),"Actual interrupted history state missing");Capture(window,pi,start,Path.Combine(output,"interrupted-history.png"));result["interrupted_history_verified"]=true;}
 foreach(var item in before)Require(File.Exists(item.Key)&&FileHash(item.Key)==item.Value,"Original protected fixture changed");Save(Path.Combine(output,"protected-hashes.json"),before);result["source_foreign_preserved"]=true;result["no_download_invoked"]=true;
 }
 public static string Run(string exe,string root,string output,string mode){Dictionary<string,object> result=new Dictionary<string,object>();string caseFile=Plain(Path.Combine(root,"gui-recovery-case.json"),root);Require(new FileInfo(caseFile).Length<=65536,"Manifest bound");originalProtected=Protected(new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(caseFile)),root);result["binary_sha256_before"]=FileHash(exe);result["mode"]=mode;result["status"]="FAIL";result["input_before"]=Input();string name="dlpad-cookie-"+Guid.NewGuid().ToString("N");result["private_desktop"]=name;IntPtr desktop=IntPtr.Zero,job=IntPtr.Zero,window=IntPtr.Zero;PI pi=new PI();long start=0;bool restored=false;Thread worker=null;Exception workerError=null;
 try{desktop=CreateDesktop(name,IntPtr.Zero,IntPtr.Zero,0,0x1ff,IntPtr.Zero);Require(desktop!=IntPtr.Zero,"Create private desktop");job=CreateJobObject(IntPtr.Zero,null);Require(job!=IntPtr.Zero,"Create owned Job");Limits limits=new Limits();limits.basic.flags=0x2000;Require(SetInformationJobObject(job,9,ref limits,(uint)Marshal.SizeOf(typeof(Limits))),"Set owned Job kill-on-close");SI si=new SI();si.cb=Marshal.SizeOf(typeof(SI));si.desktop=name;Require(CreateProcess(exe,new StringBuilder("\""+exe+"\" --fixture"),IntPtr.Zero,IntPtr.Zero,false,0x08000004,IntPtr.Zero,Path.GetDirectoryName(exe),ref si,out pi),"Create suspended app");if(!AssignProcessToJobObject(job,pi.process)){TerminateProcess(pi.process,91);throw new Exception("Owned Job binding failed before resume");}long e,k,u;Require(GetProcessTimes(pi.process,out start,out e,out k,out u),"App start identity");result["pid"]=pi.pid;result["start_filetime"]=start;Require(ResumeThread(pi.thread)!=0xffffffff,"Resume owned app");for(int i=0;i<150&&window==IntPtr.Zero;i++){int count=0;EnumDesktopWindows(desktop,delegate(IntPtr h,IntPtr l){if(++count>64)return false;uint id;GetWindowThreadProcessId(h,out id);if(id==pi.pid&&IsWindowVisible(h)){StringBuilder title=new StringBuilder(256);GetWindowText(h,title,256);if(title.ToString()=="dlpad"){Require(window==IntPtr.Zero||window==h,"Duplicate owned dlpad windows");window=h;}}return true;},IntPtr.Zero);if(WaitForSingleObject(pi.process,0)==0)break;Thread.Sleep(100);}Require(window!=IntPtr.Zero,"Owned visible HWND missing");result["hwnd"]=window.ToInt64();Owned(window,pi,start);StringBuilder windowClass=new StringBuilder(256);GetClassName(window,windowClass,256);result["window_class"]=windowClass.ToString();Rect windowRect;Require(GetClientRect(window,out windowRect),"Owned client metadata");result["client_width"]=windowRect.right;result["client_height"]=windowRect.bottom;
 worker=new Thread(delegate(){IntPtr previous=GetThreadDesktop(GetCurrentThreadId());try{Require(SetThreadDesktop(desktop),"MTA private desktop binding");Owned(window,pi,start);Capture(window,pi,start,Path.Combine(output,"before-uia.png"));AutomationElement app=Activate(window,pi,start,output);Require(app!=null&&app.Current.ProcessId==pi.pid,"UIA root identity");VerifyRecovery(app,window,pi,start,root,output,result);
 Owned(window,pi,start);Require(PostMessage(window,0x10,IntPtr.Zero,IntPtr.Zero),"Owned WM_CLOSE");Require(WaitForSingleObject(pi.process,5000)==0,"WM_CLOSE did not exit (no global input fallback)");result["wm_close_exited"]=true;Require(FileHash(exe)==(string)result["binary_sha256_before"],"Immutable app binary changed");result["binary_sha256_after"]=FileHash(exe);result["status"]="PASS";
 }catch(Exception error){workerError=error;}finally{restored=SetThreadDesktop(previous);}});worker.IsBackground=true;worker.SetApartmentState(ApartmentState.MTA);worker.Start();Require(worker.Join(90000),"UIA worker deadline exceeded");if(workerError!=null)throw workerError;Require(restored,"MTA desktop restoration failed");result["mta_desktop_restored"]=restored;
 }catch(Exception error){result["error"]=error.GetType().FullName+": "+error.Message;result["status"]="FAIL";}
 finally{if(job!=IntPtr.Zero){Accounting accounting;bool queried=QueryInformationJobObject(job,1,out accounting,(uint)Marshal.SizeOf(typeof(Accounting)),IntPtr.Zero);result["owned_job_naturally_empty"]=queried&&accounting.active==0;result["owned_job_active_before_cleanup"]=queried?(object)accounting.active:null;if(!queried||accounting.active!=0){result["status"]="FAIL";result["owned_job_terminated"]=TerminateJobObject(job,92);}bool empty=false;for(int i=0;i<100;i++){if(QueryInformationJobObject(job,1,out accounting,(uint)Marshal.SizeOf(typeof(Accounting)),IntPtr.Zero)&&accounting.active==0){empty=true;break;}Thread.Sleep(50);}result["owned_job_empty_after_cleanup"]=empty;if(!empty)result["status"]="FAIL";CloseHandle(job);}if(pi.process!=IntPtr.Zero){bool gone=WaitForSingleObject(pi.process,5000)==0;result["owned_process_exited_after_job_close"]=gone;if(!gone)result["status"]="FAIL";CloseHandle(pi.process);}if(pi.thread!=IntPtr.Zero)CloseHandle(pi.thread);if(desktop!=IntPtr.Zero){bool closed=CloseDesktop(desktop);result["private_desktop_closed"]=closed;if(!closed)result["status"]="FAIL";}try{string after=Input();result["input_after"]=after;result["input_desktop_unchanged"]=after==(string)result["input_before"];if(!(bool)result["input_desktop_unchanged"])result["status"]="FAIL";}catch(Exception error){result["input_query_error"]=error.Message;result["status"]="FAIL";}}
 return new JavaScriptSerializer().Serialize(result);}
}

public static class Program {public static int Main(string[] a){try{if(a.Length!=3)throw new Exception("Arguments CPUexe ownedroot freshoutput");string exe=Path.GetFullPath(a[0]),root=Path.GetFullPath(a[1]),output=Path.GetFullPath(a[2]);if(!Path.IsPathRooted(a[0])||!Path.IsPathRooted(a[1])||!Path.IsPathRooted(a[2])||!File.Exists(exe)||!Directory.Exists(root)||Directory.Exists(output)||File.Exists(output))throw new Exception("Original paths/fresh output required");Directory.CreateDirectory(output);Environment.SetEnvironmentVariable("DLPAD_TEST_DATA",Path.Combine(root,"data"));Environment.SetEnvironmentVariable("DLPAD_LIBRARY_ROOT",Path.Combine(root,"media"));foreach(string key in new[]{"DLPAD_YTDLP","DLPAD_GUARDIAN_BACKEND","DLPAD_TEST_GUARDIAN_EXECUTABLE"})Environment.SetEnvironmentVariable(key,null);string r=ManagedRecoveryGui.Run(exe,root,output,"managed-startup");File.WriteAllText(Path.Combine(output,"native-result.json"),r);Console.WriteLine(r);return r.Contains("\"status\":\"PASS\"")?0:2;}catch(Exception e){Console.Error.WriteLine(e.GetType().Name+": "+e.Message);return 2;}}}
